// Module: digilent_arty_s7__bus___interconnect__arbiter__rr
//------------------------------------------------------------------------------

module digilent_arty_s7__bus___interconnect__arbiter__rr (
    output reg           builder_grant,
    input  wire    [1:0] builder_request,
    (* dont_touch = "true" *)
    input  wire          sys_clk,
    input  wire          sys_rst
);


//------------------------------------------------------------------------------
// Signals
//------------------------------------------------------------------------------


//------------------------------------------------------------------------------
// Submodules
//------------------------------------------------------------------------------


//------------------------------------------------------------------------------
// Combinatorial Logic
//------------------------------------------------------------------------------



//------------------------------------------------------------------------------
// Synchronous Logic
//------------------------------------------------------------------------------

always @(posedge sys_clk) begin
    case (builder_grant)
        1'd0: begin
            if ((~builder_request[0])) begin
                if (builder_request[1]) begin
                    builder_grant <= 1'd1;
                end
            end
        end
        1'd1: begin
            if ((~builder_request[1])) begin
                if (builder_request[0]) begin
                    builder_grant <= 1'd0;
                end
            end
        end
    endcase
    if (sys_rst) begin
        builder_grant <= 1'd0;
    end
end


//------------------------------------------------------------------------------
// Specialized Logic
//------------------------------------------------------------------------------

endmodule

