    output wire          main_basesoc_interface_stb,
    output wire          main_basesoc_interface_we,
    output wire          main_basesoc_wb_sdram_ack,
    input  wire   [29:0] main_basesoc_wb_sdram_adr,
    input  wire          main_basesoc_wb_sdram_cyc,
    output reg    [31:0] main_basesoc_wb_sdram_dat_r,
    input  wire   [31:0] main_basesoc_wb_sdram_dat_w,
    input  wire    [3:0] main_basesoc_wb_sdram_sel,
    input  wire          main_basesoc_wb_sdram_stb,
    input  wire          main_basesoc_wb_sdram_we,
    (* dont_touch = "true" *)
    input  wire          sys_clk,
    input  wire          sys_rst
);


//------------------------------------------------------------------------------
// Signals
//------------------------------------------------------------------------------

reg     [1:0] main_basesoc_adr_offset_r = 2'd0;
wire    [8:0] main_basesoc_data_port_adr;
wire  [127:0] main_basesoc_data_port_dat_r;
reg   [127:0] main_basesoc_data_port_dat_w = 128'd0;
reg    [15:0] main_basesoc_data_port_we = 16'd0;
wire          main_basesoc_tag_di_dirty;
wire   [20:0] main_basesoc_tag_di_tag;
wire          main_basesoc_tag_do_dirty;
wire   [20:0] main_basesoc_tag_do_tag;
wire    [8:0] main_basesoc_tag_port_adr;
wire   [21:0] main_basesoc_tag_port_dat_r;
wire   [21:0] main_basesoc_tag_port_dat_w;
